import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import { cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { consultasApi, medicosApi, pacientesApi } from '../../src/api';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { ConsultasPage } from '../../src/pages/recepcao/ConsultasPage';

vi.mock('../../src/api', () => ({
  consultasApi: { listar: vi.fn(), confirmar: vi.fn(), cancelar: vi.fn(), falta: vi.fn(), remarcar: vi.fn() },
  medicosApi: { listar: vi.fn(), horarios: vi.fn() },
  pacientesApi: { listar: vi.fn(), criar: vi.fn() },
}));

const CONSULTAS = [
  {
    id: 1,
    inicio: '2026-10-20 14:00',
    pacienteNome: 'Ana Pereira',
    medicoNome: 'Dr. Carlos Almeida',
    especialidadeNome: 'Clínica Geral',
    valorCentavos: 15000,
    status: 'AGENDADA',
  },
  {
    id: 2,
    inicio: '2026-10-27 09:00',
    pacienteNome: 'João Santos',
    medicoNome: 'Dra. Beatriz Souza',
    especialidadeNome: 'Cardiologia',
    valorCentavos: 27000,
    status: 'AGENDADA',
  },
];

function montar() {
  return render(
    <MemoryRouter>
      <ToastProvider>
        <ConsultasPage />
      </ToastProvider>
    </MemoryRouter>,
  );
}

async function montarComLista() {
  const utils = montar();
  await screen.findByText('2 consulta(s) encontrada(s).');
  return utils;
}

function aplicarFiltros() {
  fireEvent.click(screen.getByRole('button', { name: 'Filtrar' }));
}

describe('pages/recepcao/ConsultasPage', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
    medicosApi.listar.mockResolvedValue([{ id: 1, nome: 'Dr. Carlos Almeida' }]);
    pacientesApi.listar.mockResolvedValue([
      { id: 1, nome: 'Ana Pereira', usuarioId: 10, ativo: true },
      { id: 2, nome: 'João Santos', usuarioId: 11, ativo: true },
    ]);
    consultasApi.listar.mockResolvedValue(CONSULTAS);
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-INT-218
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF10.3
   * @objetivo Listar todas as consultas da clínica com paciente, médico e contagem
   * @resultadoEsperado A tabela tem as colunas Paciente e Médico e a contagem de resultados
   */
  test('ConsultasPage lista todas as consultas com paciente e médico', async () => {
    const { container } = await montarComLista();

    const cabecalho = within(container.querySelector('thead'));
    expect(cabecalho.getByText('Paciente')).toBeInTheDocument();
    expect(cabecalho.getByText('Médico')).toBeInTheDocument();
    expect(container.querySelectorAll('tbody tr')).toHaveLength(2);
  });

  /**
   * @caso CT-INT-219
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF10.3
   * @objetivo Refazer a listagem com os filtros aplicados pela recepção
   * @resultadoEsperado Filtrar chama a API de novo com dataInicio e status escolhidos
   */
  test('ConsultasPage refaz a listagem com os filtros aplicados', async () => {
    await montarComLista();

    fireEvent.change(screen.getByLabelText('De'), { target: { value: '2026-10-01' } });
    fireEvent.change(screen.getByLabelText('Status'), { target: { value: 'AGENDADA' } });
    aplicarFiltros();

    await waitFor(() => expect(consultasApi.listar).toHaveBeenCalledTimes(2));
    expect(consultasApi.listar).toHaveBeenLastCalledWith({
      dataInicio: '2026-10-01',
      dataFim: '',
      status: 'AGENDADA',
      medicoId: '',
      pacienteId: '',
    });
  });

  /**
   * @caso CT-INT-220
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Oferecer limpar os filtros somente quando há filtro aplicado
   * @resultadoEsperado O botão Limpar aparece após filtrar e, ao ser clicado, zera os parâmetros
   */
  test('ConsultasPage só mostra Limpar com filtro ativo e zera os parâmetros', async () => {
    await montarComLista();

    expect(screen.queryByRole('button', { name: 'Limpar' })).not.toBeInTheDocument();

    fireEvent.change(screen.getByLabelText('Status'), { target: { value: 'AGENDADA' } });
    aplicarFiltros();
    await waitFor(() => expect(consultasApi.listar).toHaveBeenCalledTimes(2));

    fireEvent.click(screen.getByRole('button', { name: 'Limpar' }));

    await waitFor(() => expect(consultasApi.listar).toHaveBeenCalledTimes(3));
    expect(consultasApi.listar).toHaveBeenLastCalledWith({
      dataInicio: '',
      dataFim: '',
      status: '',
      medicoId: '',
      pacienteId: '',
    });
  });

  /**
   * @caso CT-INT-221
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.5, RN29
   * @objetivo Registrar a falta do paciente pela recepção a partir da linha da consulta
   * @resultadoEsperado O botão Falta chama a API com o id e exibe o aviso com o nome do paciente
   */
  test('ConsultasPage registra falta do paciente pela linha da consulta', async () => {
    consultasApi.falta.mockResolvedValue({ id: 1, status: 'FALTA' });
    const { container } = await montarComLista();

    fireEvent.click(container.querySelector('tr[data-consulta-id="1"] [data-acao="falta"]'));

    await waitFor(() => expect(consultasApi.falta).toHaveBeenCalledWith(1));
    expect(await screen.findByText('Falta registrada para Ana Pereira.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-222
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.2, RN26
   * @objetivo Exigir motivo ao cancelar pela recepção e enviá-lo à API
   * @resultadoEsperado O diálogo pede o motivo e cancelar é chamado com id e texto digitado
   */
  test('ConsultasPage cancela com motivo informado pela recepção', async () => {
    consultasApi.cancelar.mockResolvedValue({ id: 2, status: 'CANCELADA' });
    const { container } = await montarComLista();

    fireEvent.click(container.querySelector('tr[data-consulta-id="2"] [data-acao="cancelar"]'));
    await screen.findByRole('dialog', { name: 'Cancelar consulta' });
    fireEvent.change(screen.getByLabelText('Motivo do cancelamento'), { target: { value: 'Paciente desistiu' } });
    fireEvent.click(screen.getByRole('button', { name: 'Cancelar consulta' }));

    await waitFor(() => expect(consultasApi.cancelar).toHaveBeenCalledWith(2, 'Paciente desistiu'));
    expect(await screen.findByText('Consulta cancelada.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-223
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Mostrar a falha da listagem como alerta em português na página
   * @resultadoEsperado Erro da API vira alerta com o id da mensagem da página
   */
  test('ConsultasPage exibe o erro da listagem como alerta', async () => {
    consultasApi.listar.mockRejectedValue(new Error('Status inválido.'));

    montar();

    const aviso = await screen.findByRole('alert');
    expect(aviso).toHaveAttribute('id', 'consultas-mensagem');
    expect(aviso).toHaveTextContent('Status inválido.');
  });
});

frontend/__testes__/integracao/seletor-h.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { medicosApi } from '../../src/api';
import { SeletorHorarios } from '../../src/components/SeletorHorarios';

vi.mock('../../src/api', () => ({
  medicosApi: { horarios: vi.fn() },
}));

function montar(props = {}) {
  return render(
    <SeletorHorarios
      id="agendar-horarios"
      medicoId="1"
      data="2026-10-26"
      selecionado={null}
      onEscolher={vi.fn()}
      recarregarChave={0}
      {...props}
    />,
  );
}

describe('components/SeletorHorarios', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(cleanup);

  /**
   * @caso CT-INT-180
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF07.1
   * @objetivo Não consultar a API quando o usuário ainda não escolheu médico e data
   * @resultadoEsperado Sem médico ou data, nenhuma chamada é feita e o grupo fica vazio
   */
  test('SeletorHorarios não busca horários sem médico ou sem data', () => {
    montar({ medicoId: '', data: '' });

    expect(medicosApi.horarios).not.toHaveBeenCalled();
    const grupo = document.getElementById('agendar-horarios');
    expect(grupo).toHaveAttribute('aria-busy', 'false');
    expect(grupo.querySelectorAll('button')).toHaveLength(0);
  });

  /**
   * @caso CT-INT-181
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF07.1, RN14
   * @objetivo Listar os horários livres devolvidos pela API como botões escolhíveis
   * @resultadoEsperado Os horários viram botões com data-inicio e a hora visível no rótulo
   */
  test('SeletorHorarios lista os horários devolvidos pela API', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });

    montar();

    expect(medicosApi.horarios).toHaveBeenCalledWith('1', '2026-10-26');
    expect(await screen.findByRole('button', { name: '08:00' })).toHaveAttribute('data-inicio', '2026-10-26 08:00');
    expect(screen.getByRole('button', { name: '08:30' })).toHaveAttribute('data-inicio', '2026-10-26 08:30');
  });

  /**
   * @caso CT-INT-182
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Avisar em português quando não há nenhum horário livre na data
   * @resultadoEsperado Lista vazia mostra o aviso "Nenhum horário livre nesta data. Tente outro dia."
   */
  test('SeletorHorarios avisa quando a data não tem horários livres', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: [] });

    montar({ data: '2026-10-27' });

    expect(await screen.findByText('Nenhum horário livre nesta data. Tente outro dia.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-183
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Exibir a mensagem de erro da API sem quebrar o formulário de agendamento
   * @resultadoEsperado Falha na busca aparece como aviso com o texto do erro
   */
  test('SeletorHorarios exibe o erro da API como aviso', async () => {
    medicosApi.horarios.mockRejectedValue(new Error('Data inválida. Use o formato AAAA-MM-DD.'));

    montar({ data: '2026-13-40' });

    expect(await screen.findByText('Data inválida. Use o formato AAAA-MM-DD.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-184
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN17
   * @objetivo Entregar o horário escolhido integralmente ao formulário de agendamento
   * @resultadoEsperado Clicar no botão chama onEscolher com "AAAA-MM-DD HH:mm" completo
   */
  test('SeletorHorarios entrega o horário completo ao clicar', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });
    const aoEscolher = vi.fn();

    montar({ onEscolher: aoEscolher });

    fireEvent.click(await screen.findByRole('button', { name: '08:30' }));

    expect(aoEscolher).toHaveBeenCalledWith('2026-10-26 08:30');
  });

  /**
   * @caso CT-INT-185
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Destacar o horário já escolhido pelo usuário
   * @resultadoEsperado O horário selecionado tem aria-pressed true e a classe selecionado
   */
  test('SeletorHorarios marca com aria-pressed o horário selecionado', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00', '2026-10-26 08:30'] });

    montar({ selecionado: '2026-10-26 08:00' });

    const escolhido = await screen.findByRole('button', { name: '08:00' });
    expect(escolhido).toHaveAttribute('aria-pressed', 'true');
    expect(escolhido).toHaveClass('selecionado');
    expect(screen.getByRole('button', { name: '08:30' })).toHaveAttribute('aria-pressed', 'false');
  });

  /**
   * @caso CT-INT-186
   * @nivel integracao
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Recarregar os horários quando a página pede (após um novo agendamento)
   * @resultadoEsperado Mudar recarregarChave dispara uma nova chamada à API de horários
   */
  test('SeletorHorarios busca de novo ao mudar recarregarChave', async () => {
    medicosApi.horarios.mockResolvedValue({ horarios: ['2026-10-26 08:00'] });

    const { rerender } = render(
      <SeletorHorarios id="agendar-horarios" medicoId="1" data="2026-10-26" selecionado={null} onEscolher={vi.fn()} recarregarChave={0} />,
    );
    await screen.findByRole('button', { name: '08:00' });

    rerender(
      <SeletorHorarios id="agendar-horarios" medicoId="1" data="2026-10-26" selecionado={null} onEscolher={vi.fn()} recarregarChave={1} />,
    );

    await waitFor(() => expect(medicosApi.horarios).toHaveBeenCalledTimes(2));
  });

  /**
   * @caso CT-INT-187
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Anunciar o grupo como ocupado enquanto os horários carregam
   * @resultadoEsperado aria-busy fica true durante a busca e volta a false ao concluir
   */
  test('SeletorHorarios mantém aria-busy true enquanto carrega', async () => {
    let resolver;
    medicosApi.horarios.mockReturnValue(new Promise((resolverExterno) => { resolver = resolverExterno; }));

    montar();

    expect(document.getElementById('agendar-horarios')).toHaveAttribute('aria-busy', 'true');
    resolver({ horarios: [] });
    await waitFor(() => expect(document.getElementById('agendar-horarios')).toHaveAttribute('aria-busy', 'false'));
  });
});

frontend/__testes__/integracao/login-pag.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { authApi } from '../../src/api';
import { AuthProvider } from '../../src/contexts/AuthContext';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { LoginPage } from '../../src/pages/LoginPage';

vi.mock('../../src/api', () => ({
  authApi: { login: vi.fn(), me: vi.fn(), registrar: vi.fn() },
  especialidadesApi: { listar: vi.fn(), criar: vi.fn() },
  medicosApi: { listar: vi.fn(), horarios: vi.fn(), criar: vi.fn() },
  pacientesApi: { listar: vi.fn(), criar: vi.fn() },
  consultasApi: { listar: vi.fn(), agendar: vi.fn() },
  adminApi: { definirAtivo: vi.fn(), resumo: vi.fn() },
}));

function montar() {
  return render(
    <MemoryRouter initialEntries={['/login']}>
      <ToastProvider>
        <AuthProvider>
          <Routes>
            <Route path="/login" element={<LoginPage />} />
            <Route path="/cadastro" element={<div>tela de cadastro</div>} />
            <Route path="/paciente" element={<div>area do paciente</div>} />
          </Routes>
        </AuthProvider>
      </ToastProvider>
    </MemoryRouter>,
  );
}

function preencher(email, senha) {
  fireEvent.change(screen.getByLabelText('E-mail'), { target: { value: email } });
  fireEvent.change(screen.getByLabelText('Senha'), { target: { value: senha } });
}

describe('pages/LoginPage', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-INT-194
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Apresentar o formulário com rótulos associados e botão de envio identificável
   * @resultadoEsperado Os campos de e-mail e senha são encontrados por rótulo e o botão Entrar está presente
   */
  test('LoginPage exibe os campos de e-mail e senha com rótulos associados', () => {
    montar();

    expect(screen.getByLabelText('E-mail')).toHaveAttribute('id', 'login-email');
    expect(screen.getByLabelText('Senha')).toHaveAttribute('id', 'login-senha');
    expect(screen.getByRole('button', { name: 'Entrar' })).toHaveAttribute('id', 'login-entrar');
    expect(document.getElementById('form-login')).not.toBeNull();
  });

  /**
   * @caso CT-INT-195
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RF02.1
   * @objetivo Oferecer o caminho de auto-cadastro para quem ainda não tem conta
   * @resultadoEsperado O link "Cadastre-se como paciente" leva para a tela de cadastro
   */
  test('LoginPage navega para a tela de cadastro pelo link indicado', () => {
    montar();

    fireEvent.click(screen.getByText('Cadastre-se como paciente'));

    expect(screen.getByText('tela de cadastro')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-196
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Mostrar a recusa de credenciais em português sem sair da tela de login
   * @resultadoEsperado Senha errada exibe alerta com a mensagem da API e mantém /login
   */
  test('LoginPage exibe erro em português para senha incorreta', async () => {
    authApi.login.mockRejectedValue(new Error('E-mail ou senha inválidos.'));
    montar();

    preencher('recepcao@clinica.com', 'senha-errada');
    fireEvent.click(screen.getByRole('button', { name: 'Entrar' }));

    const aviso = await screen.findByRole('alert');
    expect(aviso).toHaveAttribute('id', 'login-mensagem');
    expect(aviso).toHaveTextContent('E-mail ou senha inválidos.');
    expect(authApi.login).toHaveBeenCalledWith('recepcao@clinica.com', 'senha-errada');
    expect(screen.queryByText('area do paciente')).not.toBeInTheDocument();
  });

  /**
   * @caso CT-INT-197
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF01.1, RF01.3
   * @objetivo Entrar com credenciais válidas e seguir para a área do perfil
   * @resultadoEsperado Login PACIENTE salva o token, mostra o toast de boas-vindas e vai para /paciente
   */
  test('LoginPage autentica e leva o paciente para a área dele', async () => {
    authApi.login.mockResolvedValue({
      token: 'tok-1',
      usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' },
    });
    montar();

    preencher('ana@email.com', 'Senha123');
    fireEvent.click(screen.getByRole('button', { name: 'Entrar' }));

    await waitFor(() => expect(screen.getByText('area do paciente')).toBeInTheDocument());
    expect(localStorage.getItem('clinica.token')).toBe('tok-1');
    expect(await screen.findByText('Que bom ter você de volta, Ana.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-198
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo protecao-contra-erro-do-usuario
   * @requisito RNF06
   * @objetivo Impedir envio repetido enquanto o login está em andamento
   * @resultadoEsperado Durante a requisição o botão fica desabilitado e mostra "Entrando..."
   */
  test('LoginPage desabilita o botão enquanto o login está em andamento', async () => {
    let resolver;
    authApi.login.mockReturnValue(new Promise((resolverExterno) => { resolver = resolverExterno; }));
    montar();

    preencher('ana@email.com', 'Senha123');
    fireEvent.click(screen.getByRole('button', { name: 'Entrar' }));

    expect(screen.getByRole('button', { name: 'Entrando...' })).toBeDisabled();

    resolver({ token: 'tok-2', usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' } });
    await waitFor(() => expect(screen.getByText('area do paciente')).toBeInTheDocument());
  });

  /**
   * @caso CT-INT-199
   * @nivel integracao
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.2
   * @objetivo Não exibir o formulário de login para quem já tem sessão válida
   * @resultadoEsperado Com sessão restaurada, a página redireciona sem mostrar os campos
   */
  test('LoginPage redireciona o usuário já autenticado sem exibir o formulário', async () => {
    localStorage.setItem('clinica.token', 'tok-1');
    authApi.me.mockResolvedValue({ id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' });

    montar();

    await waitFor(() => expect(screen.getByText('area do paciente')).toBeInTheDocument());
    expect(screen.queryByLabelText('E-mail')).not.toBeInTheDocument();
  });
});

frontend/__testes__/unitario/formatadore.source:
import { afterEach, describe, expect, test, vi } from 'vitest';
import {
  NOMES_DIAS,
  STATUS_CONSULTA,
  estaAtiva,
  formatarDataHora,
  formatarMoeda,
  hojeISO,
} from '../../src/utils/formatadores';

// O toLocaleString('pt-BR') usa um espaço não separável entre "R$" e o valor.
const moeda = (centavos) => formatarMoeda(centavos).replace(/\u00a0/g, ' ');

describe('utils/formatadores', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  /**
   * @caso CT-UNI-128
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN22, RF08.2
   * @objetivo Exibir o preço base da especialidade em reais no formato brasileiro
   * @resultadoEsperado formatarMoeda(15000) devolve "R$ 150,00"
   */
  test('formatarMoeda converte centavos em reais no formato pt-BR', () => {
    expect(moeda(15000)).toBe('R$ 150,00');
  });

  /**
   * @caso CT-UNI-129
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN24
   * @objetivo Exibir valor zero de retorno gratuito sem casas decimais estranhas
   * @resultadoEsperado formatarMoeda(0) devolve "R$ 0,00"
   */
  test('formatarMoeda mostra zero para o retorno gratuito', () => {
    expect(moeda(0)).toBe('R$ 0,00');
  });

  /**
   * @caso CT-UNI-130
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN23
   * @objetivo Exibir o valor com desconto de 10% do paciente idoso já arredondado
   * @resultadoEsperado formatarMoeda(27000) devolve "R$ 270,00"
   */
  test('formatarMoeda exibe o valor do desconto do paciente idoso', () => {
    expect(moeda(27000)).toBe('R$ 270,00');
  });

  /**
   * @caso CT-UNI-131
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter data e hora do padrão do sistema para o formato brasileiro com hora
   * @resultadoEsperado formatarDataHora("2026-10-19 08:30") devolve "19/10/2026 08:30"
   */
  test('formatarDataHora converte data e hora para DD/MM/AAAA HH:mm', () => {
    expect(formatarDataHora('2026-10-19 08:30')).toBe('19/10/2026 08:30');
  });

  /**
   * @caso CT-UNI-132
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter apenas a data sem inventar uma hora
   * @resultadoEsperado formatarDataHora("2026-10-19") devolve "19/10/2026"
   */
  test('formatarDataHora converte data sem hora para DD/MM/AAAA', () => {
    expect(formatarDataHora('2026-10-19')).toBe('19/10/2026');
  });

  /**
   * @caso CT-UNI-133
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
   * @objetivo Tratar entrada vazia de data sem lançar exceção
   * @resultadoEsperado formatarDataHora("") devolve string vazia
   */
  test('formatarDataHora devolve string vazia para entrada vazia', () => {
    expect(formatarDataHora('')).toBe('');
  });

  /**
   * @caso CT-UNI-134
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
   * @objetivo Tratar data nula ou indefinida sem lançar exceção
   * @resultadoEsperado formatarDataHora(null) e formatarDataHora(undefined) devolvem string vazia
   */
  test('formatarDataHora devolve string vazia para null e undefined', () => {
    expect(formatarDataHora(null)).toBe('');
    expect(formatarDataHora(undefined)).toBe('');
  });

  /**
   * @caso CT-UNI-135
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF09
   * @objetivo Disponibilizar todos os status da máquina de estados da consulta
   * @resultadoEsperado STATUS_CONSULTA lista AGENDADA, CONFIRMADA, REALIZADA, FALTA e CANCELADA nessa ordem
   */
  test('STATUS_CONSULTA cobre todos os status da máquina de estados', () => {
    expect(STATUS_CONSULTA).toEqual(['AGENDADA', 'CONFIRMADA', 'REALIZADA', 'FALTA', 'CANCELADA']);
  });

  /**
   * @caso CT-UNI-136
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN19
   * @objetivo Considerar consulta AGENDADA como ativa para os limites do paciente
   * @resultadoEsperado estaAtiva({ status: "AGENDADA" }) devolve true
   */
  test('estaAtiva reconhece consulta AGENDADA como ativa', () => {
    expect(estaAtiva({ status: 'AGENDADA' })).toBe(true);
  });

  /**
   * @caso CT-UNI-137
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN19
   * @objetivo Considerar consulta CONFIRMADA como ativa para os limites do paciente
   * @resultadoEsperado estaAtiva({ status: "CONFIRMADA" }) devolve true
   */
  test('estaAtiva reconhece consulta CONFIRMADA como ativa', () => {
    expect(estaAtiva({ status: 'CONFIRMADA' })).toBe(true);
  });

  /**
   * @caso CT-UNI-138
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN26
   * @objetivo Não tratar estados finais da consulta como ativos
   * @resultadoEsperado estaAtiva devolve false para REALIZADA, FALTA e CANCELADA
   */
  test('estaAtiva devolve false para os estados finais', () => {
    const resultados = ['REALIZADA', 'FALTA', 'CANCELADA'].map((status) => estaAtiva({ status }));
    expect(resultados).toEqual([false, false, false]);
  });

  /**
   * @caso CT-UNI-139
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF05.1
   * @objetivo Disponibilizar os nomes dos dias da semana em português para a grade
   * @resultadoEsperado NOMES_DIAS tem 7 posições começando em "Domingo" e terminando em "Sábado"
   */
  test('NOMES_DIAS cobre a semana começando no domingo', () => {
    expect(NOMES_DIAS).toHaveLength(7);
    expect(NOMES_DIAS[0]).toBe('Domingo');
    expect(NOMES_DIAS[6]).toBe('Sábado');
  });

  /**
   * @caso CT-UNI-140
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Permitir fixar o relógio para testar o cálculo da data de hoje
   * @resultadoEsperado Com o relógio fixado em 2026-10-19T08:00:00, hojeISO devolve "2026-10-19"
   */
  test('hojeISO usa o relógio injetável e devolve a data no formato AAAA-MM-DD', () => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date('2026-10-19T08:00:00'));
    expect(hojeISO()).toBe('2026-10-19');
  });
});

frontend/__testes__/unitario/auth-contex.source:
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { cleanup, fireEvent, render, renderHook, screen, waitFor } from '@testing-library/react';
import { authApi } from '../../src/api';
import { AuthProvider, ROTA_INICIAL, useAuth } from '../../src/contexts/AuthContext';

vi.mock('../../src/api', () => ({
  authApi: { login: vi.fn(), me: vi.fn(), registrar: vi.fn() },
}));

function Sonda() {
  const { usuario, carregando, entrar, sair } = useAuth();
  return (
    <div>
      <span data-testid="usuario">{usuario ? `${usuario.perfil}:${usuario.nome}` : 'nenhum'}</span>
      <span data-testid="carregando">{String(carregando)}</span>
      <button type="button" onClick={() => entrar('ana@email.com', 'Senha123')}>entrar</button>
      <button type="button" onClick={sair}>sair</button>
    </div>
  );
}

describe('contexts/AuthContext', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  afterEach(() => {
    cleanup();
    localStorage.clear();
  });

  /**
   * @caso CT-UNI-164
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Falhar de forma previsível quando o hook é usado fora do provedor
   * @resultadoEsperado useAuth() devolve null sem AuthProvider na árvore
   */
  test('useAuth devolve null quando usado sem AuthProvider', () => {
    const { result } = renderHook(() => useAuth());

    expect(result.current).toBeNull();
  });

  /**
   * @caso CT-UNI-165
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.2
   * @objetivo Não consultar dados do usuário quando não há sessão salva
   * @resultadoEsperado Sem token, /auth/me não é chamado, carregando é false e usuário fica null
   */
  test('AuthProvider não chama /auth/me sem token no armazenamento', () => {
    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
    expect(screen.getByTestId('usuario')).toHaveTextContent('nenhum');
    expect(authApi.me).not.toHaveBeenCalled();
  });

  /**
   * @caso CT-UNI-166
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.3
   * @objetivo Restaurar a sessão do usuário a partir do token salvo
   * @resultadoEsperado Com token, /auth/me é chamado uma vez e define o usuário logado
   */
  test('AuthProvider restaura a sessão chamando /auth/me com token salvo', async () => {
    localStorage.setItem('clinica.token', 'tok-1');
    authApi.me.mockResolvedValue({ id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' });

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    expect(screen.getByTestId('carregando')).toHaveTextContent('true');
    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('PACIENTE:Ana Pereira'));
    expect(authApi.me).toHaveBeenCalledTimes(1);
    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
  });

  /**
   * @caso CT-UNI-167
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo recuperabilidade
   * @requisito RNF02
   * @objetivo Descartar a sessão quando o token salvo é rejeitado pela API
   * @resultadoEsperado /auth/me rejeitado limpa o token, zera o usuário e encerra o carregamento
   */
  test('AuthProvider descarta a sessão quando /auth/me rejeita', async () => {
    localStorage.setItem('clinica.token', 'tok-invalido');
    authApi.me.mockRejectedValue(new Error('Token inválido ou expirado.'));

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('nenhum'));
    expect(localStorage.getItem('clinica.token')).toBeNull();
    expect(screen.getByTestId('carregando')).toHaveTextContent('false');
  });

  /**
   * @caso CT-UNI-168
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RF01.1
   * @objetivo Guardar o token recebido no login e manter o usuário em memória
   * @resultadoEsperado entrar chama o login com as credenciais, salva o token e define o usuário
   */
  test('entrar autentica, salva o token e define o usuário', async () => {
    authApi.login.mockResolvedValue({
      token: 'tok-novo',
      usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' },
    });

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    fireEvent.click(screen.getByText('entrar'));

    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('PACIENTE:Ana Pereira'));
    expect(authApi.login).toHaveBeenCalledWith('ana@email.com', 'Senha123');
    expect(localStorage.getItem('clinica.token')).toBe('tok-novo');
  });

  /**
   * @caso CT-UNI-169
   * @nivel unitario
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RNF02
   * @objetivo Encerrar a sessão removendo o token do navegador
   * @resultadoEsperado sair apaga o token e zera o usuário em memória
   */
  test('sair remove o token e zera o usuário', async () => {
    authApi.login.mockResolvedValue({
      token: 'tok-1',
      usuario: { id: 1, nome: 'Ana Pereira', perfil: 'PACIENTE' },
    });

    render(
      <AuthProvider>
        <Sonda />
      </AuthProvider>,
    );

    fireEvent.click(screen.getByText('entrar'));
    await waitFor(() => expect(screen.getByTestId('usuario')).toHaveTextContent('PACIENTE:Ana Pereira'));

    fireEvent.click(screen.getByText('sair'));

    expect(screen.getByTestId('usuario')).toHaveTextContent('nenhum');
    expect(localStorage.getItem('clinica.token')).toBeNull();
  });

  /**
   * @caso CT-UNI-170
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN30
   * @objetivo Direcionar cada perfil para a rota inicial que lhe corresponde
   * @resultadoEsperado ROTA_INICIAL mapeia PACIENTE, MEDICO e RECEPCAO para as rotas da aplicação
   */
  test('ROTA_INICIAL mapeia os três perfis para as rotas corretas', () => {
    expect(ROTA_INICIAL).toEqual({
      PACIENTE: '/paciente',
      MEDICO: '/medico',
      RECEPCAO: '/recepcao',
    });
  });
});

