import { afterEach, describe, expect, test } from 'vitest';
import { cleanup, render, screen } from '@testing-library/react';
import { Campo } from '../../src/components/Campo';

afterEach(cleanup);

describe('components/Campo', () => {
  /**
   * @caso CT-INT-160
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Associar o rótulo ao campo para preenchimento por rótulo e leitor de tela
   * @resultadoEsperado getByLabelText("E-mail") encontra o input com id e tipo corretos
   */
  test('Campo associa o rótulo ao input pelo atributo for', () => {
    render(<Campo id="login-email" rotulo="E-mail" type="email" />);
    const campo = screen.getByLabelText('E-mail');
    expect(campo).toHaveAttribute('id', 'login-email');
    expect(campo).toHaveAttribute('type', 'email');
  });

  /**
   * @caso CT-INT-161
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Ligar o texto de ajuda ao campo por aria-describedby
   * @resultadoEsperado O campo aponta para o id do parágrafo de ajuda que é exibido
   */
  test('Campo conecta o texto de ajuda ao input por aria-describedby', () => {
    render(<Campo id="paciente-senha" rotulo="Senha" ajuda="Mínimo de 8 caracteres, com letras e números." />);
    const campo = screen.getByLabelText('Senha');
    expect(campo).toHaveAttribute('aria-describedby', 'paciente-senha-ajuda');
    expect(screen.getByText('Mínimo de 8 caracteres, com letras e números.')).toHaveAttribute('id', 'paciente-senha-ajuda');
  });

  /**
   * @caso CT-INT-162
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Marcar o campo obrigatório sem poluir o nome acessível
   * @resultadoEsperado O asterisco é renderizado como span oculto para leitores de tela
   */
  test('Campo marca obrigatório com asterisco oculto para leitores de tela', () => {
    const { container } = render(<Campo id="cadastro-nome" rotulo="Nome completo" obrigatorio />);
    const marca = container.querySelector('label span[aria-hidden="true"]');
    expect(marca).toHaveTextContent('*');
    expect(screen.getByLabelText(/^Nome completo/)).toHaveAttribute('id', 'cadastro-nome');
  });

  /**
   * @caso CT-INT-163
   * @nivel integracao
   * @atributo manutenibilidade
   * @subatributo modularidade
   * @requisito RNF07
   * @objetivo Permitir que a página injete um controle próprio no lugar do input padrão
   * @resultadoEsperado Com children informado, Campo renderiza o select em vez do input
   */
  test('Campo renderiza o elemento-filho informado no lugar do input padrão', () => {
    const { container } = render(
      <Campo id="filtro-status" rotulo="Status">
        <select id="filtro-status" defaultValue="">
          <option value="">Todos</option>
          <option value="AGENDADA">Agendada</option>
        </select>
      </Campo>,
    );
    expect(screen.getByLabelText('Status').tagName).toBe('SELECT');
    expect(container.querySelector('input')).toBeNull();
  });
});

frontend/__testes__/unitario/use-mensage.source:
import { afterEach, describe, expect, test } from 'vitest';
import { act, cleanup, render, renderHook, screen } from '@testing-library/react';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { useMensagem } from '../../src/hooks/useMensagem';

const envolver = ({ children }) => <ToastProvider>{children}</ToastProvider>;

describe('hooks/useMensagem', () => {
  afterEach(cleanup);

  /**
   * @caso CT-UNI-160
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Registrar a mensagem de erro com o texto em português para exibição junto ao formulário
   * @resultadoEsperado erro("...") define mensagem com tipo "erro" e o texto informado
   */
  test('useMensagem.erro define a mensagem de erro', () => {
    const { result } = renderHook(() => useMensagem(), { wrapper: envolver });

    act(() => result.current.erro('Horário indisponível.'));

    expect(result.current.mensagem).toEqual({ tipo: 'erro', texto: 'Horário indisponível.' });
  });

  /**
   * @caso CT-UNI-161
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RNF06
   * @objetivo Limpar a mensagem exibida antes de uma nova ação
   * @resultadoEsperado limpar() zera a mensagem para null
   */
  test('useMensagem.limpar zera a mensagem atual', () => {
    const { result } = renderHook(() => useMensagem(), { wrapper: envolver });

    act(() => result.current.erro('Algo falhou.'));
    act(() => result.current.limpar());

    expect(result.current.mensagem).toBeNull();
  });

  /**
   * @caso CT-UNI-162
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo reconhecibilidade
   * @requisito RNF06
   * @objetivo Mostrar o sucesso como aviso flutuante e não deixar erro antigo na tela
   * @resultadoEsperado sucesso limpa a mensagem do formulário e publica o toast com texto e título
   */
  test('useMensagem.sucesso limpa o erro e publica o toast de sucesso', () => {
    const { result } = renderHook(() => useMensagem(), { wrapper: envolver });

    act(() => result.current.erro('Erro antigo.'));
    act(() => result.current.sucesso('Consulta agendada com sucesso.', 'Tudo certo!'));

    expect(result.current.mensagem).toBeNull();
    expect(screen.getByText('Tudo certo!')).toBeInTheDocument();
    expect(screen.getByText('Consulta agendada com sucesso.')).toBeInTheDocument();
  });

  /**
   * @caso CT-UNI-163
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo testabilidade
   * @requisito RNF07
   * @objetivo Começar sem nenhuma mensagem para não exibir aviso espúrio ao montar
   * @resultadoEsperado O estado inicial de mensagem é null
   */
  test('useMensagem começa com mensagem null', () => {
    const { result } = renderHook(() => useMensagem(), { wrapper: envolver });

    expect(result.current.mensagem).toBeNull();
  });
});

